    background: linear-gradient(to bottom, rgba(9, 9, 11, 0.6), rgba(9, 9, 11, 0.9));
    z-index: 1;
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 600px;
}

.hero-content h1 {
    margin-bottom: var(--spacing-md);
}

.hero-content p {
    font-size: 1.125rem;
    margin-bottom: var(--spacing-lg);
}

/* Sections General */
.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: var(--spacing-lg);
}

.section-header h2 {
    margin-bottom: 0;
}

.view-all {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    font-size: 0.875rem;
    font-weight: 500;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: var(--spacing-lg);
}

.product-card {
    display: flex;
    flex-direction: column;
    group: hover;
}

.product-image {
    position: relative;
    aspect-ratio: 4/5;
    background-color: var(--color-surface);
    overflow: hidden;
    margin-bottom: var(--spacing-md);
    border-radius: 4px;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-normal);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.badge {
    position: absolute;
    top: 12px;
    left: 12px;
    background-color: var(--color-bg);
    color: var(--color-text-primary);
    padding: 4px 8px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-radius: 2px;
}

.product-info {
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
}

.product-title {
    font-size: 1rem;
    font-weight: 500;
    margin-bottom: 4px;
}

.product-price {
    font-family: monospace;
    font-size: 1rem;
    color: var(--color-text-secondary);
}

.add-to-cart {
    opacity: 0;
    transform: translateY(10px);
}

.product-card:hover .add-to-cart {
    opacity: 1;
    transform: translateY(0);
}

/* Deals Section */
.deals-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-xl);
    align-items: center;
}

.deals-content h2 {
    margin-bottom: var(--spacing-md);
}

.deals-content p {
    font-size: 1.125rem;
    margin-bottom: var(--spacing-lg);
}

.countdown {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-lg);
}

.time-block {
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: var(--color-bg);
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: 4px;
    border: 1px solid var(--color-border);
}

.time-num {
    font-size: 2rem;
    font-weight: 700;
    font-family: monospace;
    line-height: 1;
}

.time-label {
    font-size: 0.75rem;
    color: var(--color-text-muted);
    text-transform: uppercase;
    margin-top: 4px;
}

.colon {
    font-size: 2rem;
    font-weight: 700;
    color: var(--color-text-muted);
}

.deal-card {
    position: relative;
    border-radius: 8px;
    overflow: hidden;
}

.deal-card img {
    width: 100%;
    aspect-ratio: 1/1;
    object-fit: cover;
}

.deal-tag {
    position: absolute;
    top: 20px;
    right: 20px;
    background-color: #ef4444;
    color: white;
    font-weight: bold;
    padding: 8px 12px;
    border-radius: 4px;
    font-size: 1.125rem;
}

.deal-info {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    padding: var(--spacing-lg);
    background: linear-gradient(to top, rgba(9, 9, 11, 0.9), transparent);
}

.deal-info h3 {
    margin-bottom: var(--spacing-xs);
}

.price-container {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
}

.price-old {
    text-decoration: line-through;
    color: var(--color-text-muted);
}

.price-new {
    font-size: 1.25rem;
    font-weight: bold;
    color: #ef4444;
}

/* Editorial Section */
.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
}

.editorial-card {
    display: flex;
    flex-direction: column;
}

.editorial-image {
    aspect-ratio: 16/9;
    overflow: hidden;
    margin-bottom: var(--spacing-md);
    border-radius: 4px;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-normal);
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.03);
}

.category {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--color-text-muted);
    display: block;
    margin-bottom: var(--spacing-xs);
}

.editorial-content h3 {
    margin-bottom: var(--spacing-sm);
}

.editorial-content p {
    margin-bottom: var(--spacing-md);
}

.read-link {
    font-size: 0.875rem;
    font-weight: 500;
    border-bottom: 1px solid var(--color-border);
    padding-bottom: 2px;
}

.read-link:hover {
    border-color: var(--color-text-primary);
}

/* Footer */
.footer {
    background-color: var(--color-surface);
    border-top: 1px solid var(--color-border);
    padding-top: var(--spacing-xl);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-xl);
}

.footer-brand .logo {
    margin-bottom: var(--spacing-md);
}

.footer-brand p {
    margin-bottom: var(--spacing-lg);
    max-width: 300px;
}

.social-links {
    display: flex;
    gap: var(--spacing-md);
}

.social-links a {
    font-size: 1.5rem;
    color: var(--color-text-secondary);
}

.social-links a:hover {
    color: var(--color-text-primary);
}

.footer-links h4 {
    margin-bottom: var(--spacing-md);
    color: var(--color-text-primary);
}

.footer-links ul {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.footer-links a {
    color: var(--color-text-secondary);
    font-size: 0.875rem;
}

.footer-links a:hover {
    color: var(--color-text-primary);
}

.footer-newsletter h4 {
    margin-bottom: var(--spacing-sm);
}

.footer-newsletter p {
    font-size: 0.875rem;
    margin-bottom: var(--spacing-md);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
}

.newsletter-form input {
    flex-grow: 1;
    background-color: var(--color-bg);
    border: 1px solid var(--color-border);
    color: var(--color-text-primary);
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-family: inherit;
    outline: none;
    transition: border-color var(--transition-fast);
}

.newsletter-form input:focus {
    border-color: var(--color-text-primary);
}

.newsletter-form button {
    padding: 0 1.25rem;
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--spacing-lg) 0;
    border-top: 1px solid var(--color-border);
    font-size: 0.875rem;
    color: var(--color-text-muted);
}

.legal-links {
    display: flex;
    gap: var(--spacing-md);
}

/* Responsive */
@media (max-width: 1024px) {
    .product-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .nav-links {
        display: none; /* In a real app, implement a hamburger menu toggle */
    }

    .mobile-menu-btn {
        display: flex;
    }

    h1 { font-size: 2.5rem; }
    h2 { font-size: 2rem; }

    .section-header {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--spacing-sm);
    }

    .deals-layout {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .footer-bottom {
        flex-direction: column;
        gap: var(--spacing-md);
        text-align: center;
    }

    /* Make Add to Cart always visible on mobile since there is no hover */
    .add-to-cart {
        opacity: 1;
        transform: none;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    // Add to cart functionality
    const cartCountEl = document.querySelector('.cart-count');
    const addToCartBtns = document.querySelectorAll('.add-to-cart');
    let cartCount = 0;

    addToCartBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            cartCount++;
            cartCountEl.textContent = cartCount;

            // Visual feedback
            const originalText = btn.textContent;
            btn.textContent = 'Added!';
            btn.style.backgroundColor = '#22c55e'; // Green
            btn.style.color = '#fff';
            btn.style.borderColor = '#22c55e';

            setTimeout(() => {
                btn.textContent = originalText;
                btn.style.backgroundColor = '';
                btn.style.color = '';
                btn.style.borderColor = '';
            }, 1500);
        });
    });

    // Newsletter form submission
    const newsletterForm = document.getElementById('newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const input = newsletterForm.querySelector('input[type="email"]');

            if (input.value) {
                const btn = newsletterForm.querySelector('button');
                const originalHTML = btn.innerHTML;

                btn.innerHTML = '<i class="ph ph-check"></i>';
                btn.style.backgroundColor = '#22c55e';

                setTimeout(() => {
                    btn.innerHTML = originalHTML;
                    btn.style.backgroundColor = '';
                    input.value = '';
                }, 2000);
            }
        });
    }

    // Mobile menu toggle (simple alert for demo)
    const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
    if (mobileMenuBtn) {
        mobileMenuBtn.addEventListener('click', () => {
            alert('Mobile menu toggle functionality would go here.');
        });
    }
});

